<div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><p class="text-uppercase small text-primary fw-bold mb-1">Administrator</p><h1 class="h2 mb-1">Scholarship applications</h1><p class="text-muted mb-0">Applications submitted through the public portal.</p></div><span class="badge text-bg-secondary"><?= count($applications) ?> total</span></div>
